    valuesBadge("مقاسات",sizes);valuesBadge("ألوان",colors);
    if(item.variantCount>1||sizes.length||colors.length)badges.push('<span class="catalog-summary-badge" aria-label="'+U.escape("عدد التركيبات: "+item.variantCount)+'">'+U.escape("تركيبات: "+item.variantCount)+'</span>');
    if(item.hasExpiryTracking)badges.push('<span class="catalog-summary-badge" title="تتبع الصلاحية مفعّل للمنتج">صلاحية</span>');
    else if(item.hasBatchTracking)badges.push('<span class="catalog-summary-badge" title="تتبع التشغيلات مفعّل للمنتج">تشغيلات</span>');
    if(item.hasImeiTracking)badges.push('<span class="catalog-summary-badge" title="تتبع IMEI مفعّل للمنتج">IMEI</span>');
